{
  "meta": {
    "title": "Why a Slow Store Broke Checkout",
    "topicClass": "concept",
    "format": "full",
    "targetLengthSec": 80
  },
  "story": {
    "devices": [
      "planted_question",
      "real_incident",
      "versus_split",
      "failure_before_fix"
    ],
    "hook": {
      "kind": "problem"
    },
    "runningExample": "One shopper's checkout request at Larkspur Pay spends one token from a shared bucket before it may call the payment provider.",
    "chapters": [
      {
        "id": "bucket",
        "title": "Token bucket"
      },
      {
        "id": "shared",
        "title": "One shared store"
      },
      {
        "id": "outage",
        "title": "When the store slows"
      }
    ],
    "beats": [
      {
        "id": "b1",
        "chapterId": "outage",
        "intent": "Checkout requests fail for 47 minutes and 31% of them error, leaving the question: why did a store failover break the rate limiter?",
        "device": "real_incident",
        "targetSec": 8,
        "factIds": [
          "fact-19",
          "fact-20"
        ],
        "hookNumberIds": [
          "num-18",
          "num-19"
        ],
        "continuesPrevious": false,
        "layoutMode": "centered_focus",
        "source": "Larkspur Pay post-incident report, 14 March 2025"
      },
      {
        "id": "b2",
        "chapterId": "bucket",
        "intent": "One checkout request spends one token; the bucket holds at most 100 tokens and refills at 10 per second, so bursts stay bounded.",
        "targetSec": 9,
        "factIds": [
          "fact-1",
          "fact-2",
          "num-1",
          "num-2"
        ],
        "newTerms": [
          "token bucket"
        ],
        "continuesPrevious": false,
        "layoutMode": "stacked_list"
      },
      {
        "id": "b3",
        "chapterId": "bucket",
        "intent": "As time passes the bucket refills up to its cap; an empty bucket turns the next request into 429 with a wait hint for when the next token arrives.",
        "targetSec": 10,
        "factIds": [
          "fact-3",
          "fact-5",
          "num-26"
        ],
        "continuesPrevious": true
      },
      {
        "id": "b4",
        "chapterId": "shared",
        "intent": "Per-node buckets would give a client spread across 24 gateways 24 times its limit; one shared store is chosen instead.",
        "device": "versus_split",
        "targetSec": 10,
        "factIds": [
          "fact-7",
          "num-3"
        ],
        "newTerms": [
          "shared store"
        ],
        "continuesPrevious": false,
        "layoutMode": "versus_split",
        "suggestedPatternIds": [
          "versus_split"
        ]
      },
      {
        "id": "b5",
        "chapterId": "shared",
        "intent": "Inside the shared store, the read-refill-write must run as one atomic step; otherwise two nodes can both spend the last token and both requests pass.",
        "targetSec": 10,
        "factIds": [
          "fact-6"
        ],
        "continuesPrevious": false,
        "layoutMode": "hub_spoke",
        "suggestedPatternIds": [
          "atomic_lock"
        ]
      },
      {
        "id": "b6",
        "chapterId": "outage",
        "intent": "A routine failover moves the limiter store to another zone, store calls rise from 1 ms to 80 ms, and the limiter fails open instead of enforcing globally.",
        "device": "real_incident",
        "targetSec": 12,
        "factIds": [
          "fact-20",
          "fact-21",
          "num-20",
          "num-21"
        ],
        "newTerms": [
          "fail open"
        ],
        "continuesPrevious": false,
        "layoutMode": "near_far",
        "source": "Larkspur Pay post-incident report, 14 March 2025"
      },
      {
        "id": "b7",
        "chapterId": "outage",
        "intent": "With fail open, each of the 40 checkout instances enforces the full limit alone and downstream traffic hits roughly 40 times the contract, so the provider throttles everyone.",
        "device": "failure_before_fix",
        "targetSec": 11,
        "factIds": [
          "fact-21",
          "fact-22",
          "num-22",
          "num-23"
        ],
        "continuesPrevious": true
      },
      {
        "id": "b8",
        "chapterId": "outage",
        "intent": "Larkspur makes the payment-provider limiter refuse instead of let through, divides local limits by the instance count, and raises the store timeout to 150 ms.",
        "targetSec": 10,
        "factIds": [
          "fact-23",
          "num-25"
        ],
        "continuesPrevious": true
      }
    ],
    "plantedQuestion": {
      "text": "Why did a store failover break checkout?",
      "beatId": "b1",
      "payoffBeatId": "b6"
    },
    "rejectedAlternative": {
      "beatId": "b4",
      "summary": "Each gateway node keeps its own bucket instead of one shared store.",
      "chosenBeatId": "b5"
    },
    "ending": {
      "kind": "spec_card_ending",
      "cta": "Follow for the next system design trade-off.",
      "specCard": {
        "lines": [
          "Token bucket per key",
          "One atomic store script",
          "Refuse on store failure"
        ]
      }
    },
    "missingPrimitiveRequests": [
      {
        "name": "token bucket",
        "description": "A bucket with a visible token count that drains on each request and refills over time.",
        "fallbackUsed": "counter"
      }
    ]
  }
}

